package com.bqsqwad.heartbreakhealer.feature.entertainment

/** Five further original ten-part stories with complete endings. */
internal object StoryLibraryBatch7 {
    val stories = listOf(
        StorySeries("the_old_boathouse", "The Old Boathouse", "A group of students helps a riverside club recover its history and create a safer youth programme.", listOf(
            StoryPart(1, "The Painted Door", listOf("Mira joined the riverside clean-up and found an old boathouse covered in peeling blue paint. A brass plate said it had once been a youth rowing club.", "The club had closed after the riverbank changed, and the building was now used for storage. Mira wondered whether it could serve the neighbourhood again.")),
            StoryPart(2, "The Club Register", listOf("The community archive held a register with names of young members and dates of local regattas. The final page listed a planned safety upgrade that had never been completed.", "Mira asked the council whether the building had been inspected recently. The answer was no, so the group agreed not to enter until a professional assessment was arranged.")),
            StoryPart(3, "A Former Coach", listOf("A retired coach, Mr Bako, visited the clean-up and explained that the club had taught teamwork and water safety. He had kept the original training schedule and a photograph of the last team.", "He also explained why the club closed: the river current had become unpredictable after nearby construction, and the club could not meet the updated safety requirements.")),
            StoryPart(4, "The Inspection Report", listOf("The council arranged an inspection. The boathouse needed roof repairs and accessible facilities, while any water activity would require a separate safety review and qualified supervision.", "Mira's group prepared a proposal that focused first on repairing the building as a community learning space, not immediately restarting rowing.")),
            StoryPart(5, "The Missing Trophy", listOf("The photograph showed a trophy that was absent from the archive. Mr Bako remembered it had been loaned to a local school for an exhibition.", "The school found the trophy in its display cabinet, along with a note crediting the youth club. It agreed to return it for the boathouse history display.")),
            StoryPart(6, "A Different Kind of Club", listOf("The students suggested starting with river ecology lessons, first-aid awareness sessions led by trained adults, and supervised litter surveys from safe public paths.", "A local environmental group offered to lead the first workshops. The council approved the plan once responsibilities and access rules were written down.")),
            StoryPart(7, "The Repair Fund", listOf("The building repairs cost more than the group expected. Instead of launching an uncertain fundraiser, they divided the work into approved stages and applied for a community grant.", "The grant covered the roof and accessible entrance. Local volunteers helped with painting only after the contractor confirmed the work area was safe.")),
            StoryPart(8, "Opening the Doors", listOf("The boathouse reopened as a learning centre with the old register and trophy on display. Mr Bako gave a talk about the club's history and why safety decisions mattered.", "The environmental group led the first river lesson indoors, then took students to an approved viewing point with adult supervision.")),
            StoryPart(9, "A New Register", listOf("Mira created a new register for workshops, recording attendance and consent carefully. The centre published a calendar so families knew which activities were available and who supervised them.", "Former club members donated books and photographs, while the council scheduled regular building checks.")),
            StoryPart(10, "The River's Next Chapter", listOf("At the first anniversary, the boathouse had become a busy community classroom. The old rowing club was remembered honestly, including why it had stopped operating on the river.", "Mira placed the new programme beside the old register. The building had found a useful future without ignoring the lessons of its past: a community space could thrive when enthusiasm was matched with planning, permission, and care."))
        )),
        StorySeries("the_mystery_of_room_17", "The Mystery of Room 17", "A classroom's unusual timetable leads students to uncover the story of a pioneering teacher.", listOf(
            StoryPart(1, "The Extra Room", listOf("A new timetable listed Room 17, although the school building had only sixteen numbered classrooms. Students joked that it was a room for invisible lessons.", "Lara, who helped the librarian organise school records, found an old floor plan with a small learning room marked beside the assembly hall.")),
            StoryPart(2, "The Floor Plan", listOf("The room had been converted into a storage cupboard decades earlier. A note on the plan called it the 'open lesson room' and credited a teacher named Mr Nwosu.", "The librarian remembered that Mr Nwosu had created lessons for students who needed a quieter place to study. His teaching materials might still be in the school archive.")),
            StoryPart(3, "The Lesson Cards", listOf("A box held cards with reading exercises, diagrams, and short science activities. Each card included a note explaining how the lesson could be adapted for different learners.", "Lara realised the room had been designed to make education more accessible, not to separate students. She asked the learning support coordinator to review the materials.")),
            StoryPart(4, "A Student's Letter", listOf("A letter from a former student thanked Mr Nwosu for helping her return to class after a long illness. She said the quiet room allowed her to learn at a manageable pace.", "The letter also mentioned a student-made mural that had once decorated the room. Nobody knew where it had gone.")),
            StoryPart(5, "The Mural Photograph", listOf("A yearbook photograph showed the mural behind a group of students. It displayed a tree with many branches, each labelled with a different subject.", "The art teacher recognised the style as belonging to a former student, now a professional illustrator. Lara wrote to ask about the design and whether it could be recreated.")),
            StoryPart(6, "The Artist Replies", listOf("The illustrator sent the original sketch and explained that the mural had been painted by an entire class. She asked that any new version credit the group rather than just her.", "The school checked its records and found the class list. Several former students agreed to contribute memories and help plan a new mural.")),
            StoryPart(7, "A Room Reconsidered", listOf("The principal arranged an accessibility review before deciding whether the storage room could be used again. The review recommended improved lighting, ventilation, and a clear booking system.", "The school approved a small renovation and agreed that the room would be available to any student who benefited from a quieter study space.")),
            StoryPart(8, "The New Branches", listOf("The former students and current art club recreated the tree mural using the original sketch. Each branch represented a subject, skill, or way of learning.", "The learning support coordinator helped write guidance so teachers could use the room consistently and respectfully.")),
            StoryPart(9, "The First Lesson", listOf("Room 17 reopened with a reading session led by the librarian. Students could use it for quiet study, small-group tutoring, or supervised catch-up lessons.", "The former student who had written the letter visited and met the current students. She said she was pleased the room was open to everyone who needed it.")),
            StoryPart(10, "A Number with Meaning", listOf("The school restored the number 17 to the door and added a plaque explaining the room's history. The timetable now listed it as a flexible learning space, not a mysterious extra classroom.", "Lara placed the original lesson cards in the archive and a copy of the mural sketch in the room. The mystery had ended with a space made useful again and a reminder that good education makes room for different ways to learn."))
        )),
        StorySeries("the_market_clock", "The Market Clock", "A market's broken clock reveals a forgotten agreement between traders and the town.", listOf(
            StoryPart(1, "Ten Minutes Late", listOf("The market clock had been ten minutes slow for as long as anyone could remember. When it stopped completely, trader Amaka volunteered to help find a repairer.", "Behind the clock face, the repairer found a folded paper with the words 'Market time belongs to everyone' and a date from forty years earlier.")),
            StoryPart(2, "The Agreement", listOf("The town archive held a market agreement signed by traders and the council. It set shared opening hours so deliveries, cleaning, and customer access could happen fairly.", "A later page was missing. The archive staff said it might have been removed during a building move.")),
            StoryPart(3, "The Old Caretaker", listOf("A retired market caretaker remembered the missing page. He said it recorded a change to the clock schedule after traders complained that different stalls were being given different setup times.", "He had kept a copy in his personal work folder, but it was stored with years of maintenance papers.")),
            StoryPart(4, "The Folder", listOf("The folder confirmed that all traders had agreed to the same public opening time, with separate early access for approved deliveries. The clock was meant to help everyone follow the arrangement.", "Amaka noticed that the current market rules did not mention the delivery window. She asked the market committee to review the old agreement before changing anything.")),
            StoryPart(5, "A Fair Review", listOf("The committee met with traders, cleaners, delivery workers, and the council. They agreed to keep public hours consistent and publish a clear process for early deliveries.", "The discussion also revealed that some traders had never received the current rules in writing. The committee arranged translations and printed copies.")),
            StoryPart(6, "The Clockmaker's Note", listOf("The repairer found a second note from the original clockmaker explaining that the clock had been set slightly ahead to encourage punctual opening. The practice had confused traders for years.", "The committee decided the repaired clock should show accurate time, while the official opening schedule would be displayed separately.")),
            StoryPart(7, "Repair and Reset", listOf("The clockmaker serviced the mechanism and checked it against a reliable time source. The market committee approved the new display board and asked traders to review it before installation.", "Amaka helped explain the changes at the market entrance. The new rules included a contact for questions and a date for the next review.")),
            StoryPart(8, "The First Accurate Morning", listOf("On opening day, the clock showed the correct time. Traders followed the same schedule, and delivery workers used the separate approved window.", "A few people arrived early out of habit, but the committee helped them understand the new arrangement without blame.")),
            StoryPart(9, "A Record for the Future", listOf("The archive created a digital copy of the agreement and placed the original in a protective folder. The market committee added the current rules and a record of future updates.", "The clockmaker gave the market a maintenance guide so the mechanism could be checked regularly.")),
            StoryPart(10, "Time for Everyone", listOf("At the market's anniversary, Amaka read the old agreement aloud and explained how the new schedule had been agreed. Traders thanked the workers who had helped make the process fair.", "The clock ticked above them, no longer a source of confusion. The missing page had restored the history, but the honest conversation had made the real difference: market time now belonged to everyone because everyone had helped define it."))
        )),
        StorySeries("the_blue_bus_stop", "The Blue Bus Stop", "A group of young commuters helps improve a neglected bus stop through careful research and community cooperation.", listOf(
            StoryPart(1, "The Faded Sign", listOf("Every morning, Binta waited at a bus stop whose route sign had faded until only a blue stripe remained. People often boarded the wrong bus and missed appointments.", "Binta's geography teacher encouraged her to report the issue with clear evidence rather than rely on rumours about which route served the area.")),
            StoryPart(2, "A Travel Diary", listOf("Binta and her classmates kept a one-week record of arrival times, route numbers, and accessibility problems, without recording passengers' private details.", "They discovered that the official timetable was outdated and that the stop lacked a clear notice about a temporary route change.")),
            StoryPart(3, "The Transport Office", listOf("The transport office confirmed that the route had changed during road repairs, but the temporary notice had been removed when the work ended. The permanent sign was due for replacement.", "The office asked the students to submit a simple design showing the stop name, route numbers, and a contact for service updates.")),
            StoryPart(4, "A Better Sign", listOf("The class designed a high-contrast sign with large lettering and clear symbols. They asked regular commuters to review whether it was easy to read from a safe distance.", "A visually impaired resident suggested adding a QR code for audio information, while another commuter asked for a printed timetable as well.")),
            StoryPart(5, "The Accessibility Check", listOf("The transport office arranged an accessibility review of the stop. It found that the pavement needed repair and the waiting area required a clearer path.", "The council added the pavement work to its schedule and temporarily marked a safe boarding area. The students updated their proposal to include both the sign and the waiting space.")),
            StoryPart(6, "The Missing Shelter", listOf("A bus driver remembered that a shelter had been planned but never installed after a supplier changed. The transport office found the original purchase request and confirmed that the budget had been returned.", "The students did not assume the old budget was still available. They asked the council to explain the current process for proposing a new shelter.")),
            StoryPart(7, "A Public Meeting", listOf("Commuters, drivers, nearby shopkeepers, and council staff met to discuss the stop. The group agreed on a priority list: safe pavement, accurate sign, printed timetable, then a shelter proposal.", "Binta took notes and shared them with attendees for correction before the report was submitted.")),
            StoryPart(8, "The New Stop", listOf("The pavement was repaired and the sign installed. The printed timetable included a date for review, and the QR code linked to the transport office's official route information.", "The council began assessing shelter costs and maintenance responsibilities. The students understood that a useful improvement needed a plan to keep it useful.")),
            StoryPart(9, "The First Month", listOf("Commuters reported fewer wrong-boardings, and drivers said the sign made the stop easier to identify. One route time changed, so the transport office updated the printed notice promptly.", "Binta's class added a simple feedback method and scheduled a check with the council after another month.")),
            StoryPart(10, "A Stop That Serves People", listOf("The shelter was approved after a funding and maintenance plan was agreed. The students presented their findings at school and explained how they had gathered evidence respectfully.", "The blue bus stop became easier to use because its information was clear and its path was safer. Binta kept the first faded photograph in her geography folder as a reminder: small public problems can improve when people listen, verify, and work with the right authorities."))
        )),
        StorySeries("the_sunday_recipe_box", "The Sunday Recipe Box", "A family recipe collection helps cousins understand their grandparents' community work and create a new tradition.", listOf(
            StoryPart(1, "The Wooden Box", listOf("After a family gathering, cousins Tola and Nnamdi found a wooden recipe box in their grandmother's kitchen. It contained cards in several handwritings and a list titled 'Sunday Table'.", "The list included neighbours' names beside dishes. Their grandmother explained that the family once cooked extra meals for anyone who needed a place to eat on Sundays.")),
            StoryPart(2, "More Than Recipes", listOf("Some cards included notes about who had contributed ingredients or helped deliver meals. The cousins realised the box was a record of community care as well as cooking.", "One card mentioned a community hall that had hosted the meals. The hall was now used by a different organisation.")),
            StoryPart(3, "The Hall's Archive", listOf("The hall manager allowed them to review old event programmes. They found photographs of the Sunday table and a thank-you letter from a local school.", "The letter explained that the meals had supported families during a period when the school kitchen was being repaired. The cousins had never heard this part of the story.")),
            StoryPart(4, "The Neighbour's Card", listOf("A recipe card was signed by Mrs Nkem, a neighbour who had moved away. Her family still lived nearby and shared a note explaining that she had organised the meal rota.", "The note also said the family had kept a second box of recipes, including versions adapted for allergies and different dietary needs.")),
            StoryPart(5, "A Careful Collection", listOf("Tola and Nnamdi asked relatives for permission to copy the cards. They recorded recipe names, contributor credits, and any dietary notes that people wanted included.", "Their grandmother reminded them not to publish personal health information or assume a recipe was suitable for everyone. Each card would carry a clear ingredient list.")),
            StoryPart(6, "The Community Cookbook", listOf("The cousins proposed a small cookbook for the hall's fundraiser. They checked each recipe with its contributor or family and agreed not to include anything without permission.", "A local printer offered a low-cost first run. The hall manager asked that the book also explain how the Sunday meals had been organised.")),
            StoryPart(7, "A New Sunday Table", listOf("The family and hall volunteers planned a one-day community lunch with clear food labels, allergy information, and a way for guests to ask questions privately.", "The cousins helped set tables and made sure volunteers knew which dishes had specific ingredient concerns. The event was designed to be welcoming, not to pressure anyone to explain their circumstances.")),
            StoryPart(8, "The Story Behind the Soup", listOf("At lunch, their grandmother told the story of the first Sunday table. It had started with one pot of soup and grown because neighbours offered what they could.", "A former teacher thanked the family for helping students during the school kitchen repairs. The cousins saw how a small act had become a lasting memory for many people.")),
            StoryPart(9, "A Box for the Next Generation", listOf("The family donated a copy of the cookbook to the hall and kept the original recipe cards safely at home. They added a new section for future contributions, with permission notes and dates.", "Their grandmother asked the cousins to take turns organising the next gathering, so the tradition would be shared rather than placed on one person's shoulders.")),
            StoryPart(10, "Every Seat at the Table", listOf("The next Sunday, Tola and Nnamdi hosted the meal with relatives and volunteers. The menu included old favourites and new dishes contributed by neighbours.", "They placed the wooden box at the centre of the table, not as a museum piece but as a reminder of how the tradition began. The recipes had been preserved, the contributors credited, and the community meal had a clear, sustainable plan. The cousins understood that a family legacy was not only something to inherit; it was something to care for together."))
        ))
    )
}
